function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 2000) return 's needs 1 to 2000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may only contain lowercase letters a-z.';
  return null;
}

