function distinctSubseqII(s) {
  const MOD = 1_000_000_007;
  const n = s.length;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  const last = new Array(26).fill(0);

  for (let i = 1; i <= n; i++) {
    const letter = s.charCodeAt(i - 1) - 97;
    dp[i] = (2 * dp[i - 1]) % MOD;
    if (last[letter] > 0) {
      const repeated = dp[last[letter] - 1];
      dp[i] = (dp[i] - repeated + MOD) % MOD;
    }
    last[letter] = i;
  }

  return (dp[n] - 1 + MOD) % MOD;
}

