function distinctSubseqII(s) {
  const MOD = 1_000_000_007;
  const n = s.length;
  if (n <= 12) {
    // Enumerate every choice of positions and collect the strings they spell.
    const seen = new Set();
    for (let mask = 1; mask < (1 << n); mask++) {
      let word = '';
      for (let i = 0; i < n; i++) if (mask & (1 << i)) word += s[i];
      seen.add(word);
    }
    return seen.size % MOD;
  }
  // Count each distinct subsequence once through its leftmost embedding:
  // from position i, pick the first occurrence of each letter and continue after it.
  const count = new Array(n + 1).fill(0);
  const nextAt = new Array(26).fill(-1);
  for (let i = n - 1; i >= 0; i--) {
    nextAt[s.charCodeAt(i) - 97] = i;
    let total = 0;
    for (let c = 0; c < 26; c++) {
      if (nextAt[c] !== -1) total = (total + 1 + count[nextAt[c] + 1]) % MOD;
    }
    count[i] = total;
  }
  return count[0];
}

