function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 10);
  const pick = rand();
  const alphabet = pick < 0.15 ? 1 : pick < 0.4 ? 2 : pick < 0.7 ? int(3, 5) : 26;
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + int(0, alphabet - 1));
  return [s];
}
